#include "support/process.hpp"
#include <sstream>
using namespace test;
int main(int argc,char** argv){try{check(argc==2,"nano required");std::string binary=argv[1],second="0x2B5AD5c4795c026514f8317c7a215E218DcCD6cF",third="0x6813Eb9362372EEF6200f3b1dbC3f819671cBA69",target="0xf2e246bb76df876cef8b38ae84130f4f55de395b",other="0x3333333333333333333333333333333333333333";Temp root;Env env={{"NANO_WALLET_PASSWORD","staking-test-only"}};auto genesis=root/"genesis.json";Json alloc={{other,{{"code","0x00"}}}};for(auto a:{account,second,third})alloc[a]={{"balance",quantity(Int("100000000000000000000000"))}};save(genesis,{{"config",{{"chainId",1337},{"consensus","pos"},{"stakingContract",target}}},{"alloc",alloc}});
 for(unsigned i:{1,2}){auto e=env;e["NANO_PRIVATE_KEY"]=key(i);success(run({binary,"wallet","import",(root/(std::to_string(i)+".json")).string()},e));}
 Process server({binary,"serve",genesis.string(),(root/"db").string(),"0","127.0.0.1"});int port=server.port();auto command=[&](std::vector<std::string> args){args.insert(args.begin(),{binary,"rpc",url(port)});return run(args,env);};auto cli=[&](std::vector<std::string> args){return success(command(args));};auto produce=[&]{auto selected=rpc(port,"validator_isSelected",{account})["selectedValidator"];auto block=rpc(port,"validator_getBlockTemplate",{selected});block["timestamp"]=block["number"];block.erase("hash");check(rpc(port,"validator_submitBlock",{block})["success"],"staking block production");};
 auto rejected=[&](const std::string& destination,const std::string& message){auto nonce=rpc(port,"eth_getTransactionCount",{second,"pending"}),pool=rpc(port,"txpool_status"),balance=rpc(port,"eth_getBalance",{second});for(std::string op:{"stake-register","stake-add","stake-withdraw"}){std::vector<std::string> args={op,(root/"2.json").string(),destination};if(op!="stake-withdraw")args.push_back("10000");auto r=command(args);check(r.code!=0&&r.err.find(message)!=std::string::npos,"invalid staking target accepted: "+r.err);check(rpc(port,"eth_getTransactionCount",{second,"pending"})==nonce&&rpc(port,"txpool_status")==pool&&rpc(port,"eth_getBalance",{second})==balance,"rejected staking mutated pending state");}};
 check(rpc(port,"eth_accounts")==Json::array(),"RPC holds wallets");rejected(target,"no deployed code");rejected(account,"no deployed code");rejected(other,"differs from the chain staking contract");
 Process deploy({binary,"rpc",url(port),"deploy",(root/"1.json").string(),(fs::path(NANO_TEST_SOURCE)/"contracts/NanoStaking.hex").string(),"30","10000"},env);deploy.event("submitted");produce();auto deployed=deploy.wait(35);check(deployed.code==0,deployed.err);auto deployment=Json::parse(deployed.out.substr(deployed.out.find('\n')+1));check(address(deployment["contractAddress"])==target&&quantity(rpc(port,"nno_getStake",{account}))==Int("10000000000000000000000"),"staking deployment");
 auto registered=cli({"stake-register",(root/"2.json").string(),target,"10000"});check(rpc(port,"nno_getStake",{second})=="0x0"&&address(rpc(port,"eth_getTransactionByHash",{registered["hash"]})["from"])==address(second),"registration pending semantics");produce();check(rpc(port,"eth_getTransactionReceipt",{registered["hash"]})["status"]=="0x1","registration failed");auto added=cli({"stake-add",(root/"2.json").string(),target,"1"});produce();check(rpc(port,"eth_getTransactionReceipt",{added["hash"]})["status"]=="0x1"&&quantity(rpc(port,"nno_getStake",{second}))==Int("10001000000000000000000"),"add stake failed");check(command({"stake-withdraw",(root/"2.json").string(),target}).code!=0,"early withdrawal accepted");while(quantity(rpc(port,"eth_blockNumber"))<103)produce();auto withdrawn=cli({"stake-withdraw",(root/"2.json").string(),target});check(quantity(rpc(port,"nno_getStake",{second}))==Int("10001000000000000000000"),"withdrawal mutated before inclusion");produce();check(rpc(port,"eth_getTransactionReceipt",{withdrawn["hash"]})["status"]=="0x1"&&rpc(port,"nno_getStake",{second})=="0x0"&&rpc(port,"eth_accounts")==Json::array()&&quantity(rpc(port,"eth_getBalance",{target}))==Int("10000000000000000000000"),"withdrawal or escrow balance");
 auto config=root/"validator.json";Json settings={{"nodes",Json::array({url(port)})},{"register",true},{"staking_contract",target},{"stake_nano","10000"},{"registration_timeout",5},{"max_retries",1},{"chain_id",rpc(port,"eth_chainId")},{"genesis_hash",rpc(port,"eth_getBlockByNumber",{"0x0",false})["hash"]}};save(config,settings);auto validator_env=env;validator_env["VALIDATOR_KEY"]=key(2);
 Process validator({binary,"validator",config.string(),"--once"},validator_env);auto submission=validator.event("registration_submitted");check(rpc(port,"nno_getStake",{second})=="0x0"&&address(rpc(port,"eth_getTransactionByHash",{submission["hash"]})["from"])==address(second),"validator registration pending semantics");produce();bool selected_second=rpc(port,"validator_isSelected",{second})["selected"];auto registered_height=rpc(port,"eth_blockNumber");auto result=validator.wait(10);
 auto correct_unsigned_outcome=[&](const auto& r){if(selected_second)return r.code!=0&&r.err.find("refuses unsigned block template")!=std::string::npos;std::istringstream stream(r.out);Json output;while(stream>>std::ws&&!stream.eof())stream>>output;return r.code==0&&output.value("skipped",false);};
 check(correct_unsigned_outcome(result)&&quantity(rpc(port,"nno_getStake",{second}))==Int("10000000000000000000000")&&rpc(port,"eth_blockNumber")==registered_height,"validator unsigned-production policy: "+result.err+result.out);auto nonce=rpc(port,"eth_getTransactionCount",{second,"pending"});auto repeated=run({binary,"validator",config.string(),"--once"},validator_env);check(correct_unsigned_outcome(repeated)&&repeated.out.find("registration_submitted")==std::string::npos&&rpc(port,"eth_getTransactionCount",{second,"pending"})==nonce&&rpc(port,"eth_blockNumber")==registered_height,"duplicate registration or unexpected production");
 // Always exercise the selected validator's refusal too, regardless of state-root selection.
 auto selected_for_refusal=address(rpc(port,"validator_isSelected",{account})["selectedValidator"]);
 check(selected_for_refusal==address(account)||selected_for_refusal==address(second),"unexpected selected validator");
 auto selected_env=validator_env;selected_env["VALIDATOR_KEY"]=key(selected_for_refusal==address(account)?1:2);
 auto unsigned_attempt=run({binary,"validator",config.string(),"--once"},selected_env);
 check(unsigned_attempt.code!=0&&unsigned_attempt.err.find("refuses unsigned block template")!=std::string::npos&&rpc(port,"eth_blockNumber")==registered_height,"selected validator accepted unsigned production: "+unsigned_attempt.err);
 settings["registration_timeout"]=1;save(config,settings);validator_env["VALIDATOR_KEY"]=key(3);auto height=rpc(port,"eth_blockNumber");auto expired=run({binary,"validator",config.string(),"--once"},validator_env);check(expired.code!=0&&expired.err.find("receipt timeout")!=std::string::npos,"missing registration timeout");auto pending=Json::parse(expired.out);check(pending["event"]=="registration_submitted"&&rpc(port,"eth_getTransactionReceipt",{pending["hash"]}).is_null()&&rpc(port,"nno_getStake",{third})=="0x0"&&rpc(port,"eth_blockNumber")==height&&rpc(port,"eth_getTransactionCount",{third,"pending"})=="0x1","timeout mutated stake or chain");auto pool=rpc(port,"txpool_status");auto retry=run({binary,"validator",config.string(),"--once"},validator_env);check(retry.code!=0&&retry.err.find("pending transactions")!=std::string::npos&&retry.out.find("registration_submitted")==std::string::npos&&rpc(port,"txpool_status")==pool&&rpc(port,"eth_getTransactionCount",{third,"pending"})=="0x1","retry duplicated transaction");
 auto selected=rpc(port,"validator_isSelected",{account})["selectedValidator"];check(rpc(port,"validator_submitBlock",{rpc(port,"validator_getBlockTemplate",{selected})})["success"],"include delayed registration");check(rpc(port,"eth_getTransactionReceipt",{pending["hash"]})["status"]=="0x1","delayed registration failed");bool selected_third=rpc(port,"validator_isSelected",{third})["selected"];auto resumed=run({binary,"validator",config.string(),"--once"},validator_env);bool expected_result=selected_third?(resumed.code!=0&&resumed.err.find("refuses unsigned block template")!=std::string::npos):(resumed.code==0&&Json::parse(resumed.out).value("skipped",false));check(expected_result&&resumed.out.find("registration_submitted")==std::string::npos&&rpc(port,"eth_getTransactionCount",{third,"pending"})=="0x1"&&quantity(rpc(port,"nno_getStake",{third}))==Int("10000000000000000000000"),"registration recovery failed: "+resumed.err);
 std::cout<<"Native staking CLI and registration recovery passed\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
